-- regulatory_driver
update public.fields set verification_status='verified_against_standard', verification_quote='Nach dem Wasserhaushaltsgesetz darf eine Erlaubnis für das Einleiten von Abwasser in ein Gewässer nur erteilt werden, wenn die Menge und Schädlichkeit des Abwassers nach dem Stand der Technik gering gehalten wird und die Einleitung mit den Gewässereigenschaften und den rechtlichen Anforderungen vereinbar ist. | Hilfestellung zur Ermittlung der maßgebenden Gewässerbelastung geben z. B. die Ergebnisse der Bestandsaufnahme gemäß Wasserrahmenrichtlinie (EG-WRRL). | Die Feststellung des Bedarfs einer Regenwasserbehandlung erfolgt auf Basis einer Emissions-/Immissionsanalyse, in der Regel durch die Aufsichtsbehörden. — printed p.8 (§1.2) and p.15 (§5.1)', verification_note='md-verified 2026-09-05 (§1.2/§5.1, printed p.8/15) [VC]; caveat: the four enum tokens are EKOWAI''s grouping of the three drivers the source names (WHG-Erlaubnis, EG-WRRL-Bestandsaufnahme, Emissions-/Immissionsanalyse); "sonstiges" has no source', verified_at=now() where id='db60459e-2ef0-4f4f-9318-c8c0ac2f262d' and verification_status not in ('verified_against_standard','corrected');
-- treatment_need_confirmed
update public.fields set verification_status='verified_against_standard', verification_quote='Die Feststellung des Bedarfs einer Regenwasserbehandlung erfolgt auf Basis einer Emissions-/Immissionsanalyse, in der Regel durch die Aufsichtsbehörden. Lässt sich das geforderte Gewässerschutzziel grundsätzlich durch eine Retentionsbodenfilteranlage erreichen, muss geprüft werden, ob die gegebenen Randbedingungen den Bau und den dauerhaften, wartungsarmen Betrieb eines Retentionsbodenfilterbeckens zulassen. In Bild 1 ist der Ablauf eines für eine Retentionsbodenfilteranlage notwendigen Planungsprozesses dargestellt. — printed p.15', verification_note='md-verified 2026-09-05 (§5.1, printed p.15) [VC]; caveat: Bild 1 (Flussdiagramm zur Prüfung der Umsetzbarkeit) is an image in the md (mathpix -17.jpg), its boxes are not transcribed', verified_at=now() where id='9b117576-0280-4eed-a435-9901ebadd852' and verification_status not in ('verified_against_standard','corrected');
-- wasserschutzgebiet
update public.fields set verification_status='verified_against_standard', verification_quote='Innerhalb von Wasserschutzgebieten sind die Regeln nach RiStWag zu beachten. | Bei der Straßenentwässerung gelten außerhalb von Wasserschutzgebieten die Vorgaben für das Trennsystem. Innerhalb von Wasserschutzgebieten ist zum Schutz gegen Havarien ein zusätzlicher Auffangraum für Leichtflüssigkeiten gemäß RiStWag vorzusehen. — printed p.21 (§6.1.3.3) and p.26 (§6.2.1.3)', verification_note='md-verified 2026-09-05 (§6.1.3.3/§6.2.1.3, printed p.21/26) [VC]; caveat: the guideline only distinguishes inside/outside a Wasserschutzgebiet; the zone tokens I/II/IIIa/IIIb are RiStWag''s (NR)', verified_at=now() where id='ec2bddae-2328-41a2-bea8-1a3dc5edb3f1' and verification_status not in ('verified_against_standard','corrected');

