-- fremdwasser_relevant
update public.fields set verification_status='verified_against_standard', verification_quote='Wird ein Fremdwasserzufluss festgestellt, sind Sanierungsvorschläge zu erarbeiten, die einen verfahrensgerechten Betrieb des Retentionsbodenfilters ermöglichen. Vor der Planung des Retentionsbodenfilters muss geprüft werden, ob die Maßnahmen erfolgreich waren. Kann ein relevanter Fremdwasserzufluss zu einem Retentionsbodenfilterbecken nicht beseitigt werden, müssen entweder betriebliche Maßnahmen vorgesehen werden (z. B. alternierende Beschickung hydraulisch getrennter Filterbeete) oder der Bau der Anlage muss unterbleiben. — printed p.16', verification_note='md-verified 2026-09-05 (§5.2.2, printed p.16) [VC]', verified_at=now() where id='43f21c12-7c60-4106-9076-94f181a7160d' and verification_status not in ('verified_against_standard','corrected');
