update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $e_{0}$ & \% & mittlere Jahresentlastungsrate der Vorstufe (Mischsystem) | Bestehende Entlastungsbauwerke können in der Regel als Vorstufe genutzt werden, wenn sie eine Entlastungsrate von $e_{0} \leq 55 \%$ einhalten und regelgerecht betrieben werden. In Einzelfällen kann im Bestand eine höhere Entlastungsrate zugelassen werden. — printed p.12 (§3.2) and p.26 (§6.2.1.1)', verification_note='md-verified 2026-09-05 (§3.2/§6.2.1.1, printed p.12/26) [VC]', verified_at=now() where id='c1271986-cf27-46f8-819d-acb569ef5175' and verification_status not in ('verified_against_standard','corrected');
-- b_R_e_zul
update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $b_{\mathrm{R}, \mathrm{e}, \mathrm{zul}}$ & kg/(ha•a) & zulässige spezifische jährliche Einleitfracht (AFS63) aus der Retentionsbodenfilteranlage | Als Mindestanforderung ist der Nachweis zu führen, dass mit der gewählten Anlagenkonfiguration die emissionsorientierten Vorgaben bzgl. der zulässigen spezifischen jährlichen Einleitfracht (AFS63) aus der Retentionsbodenfilteranlage $b_{\text {R, }, \text { zul }}$ für die Zielgröße AFS63 erreicht werden kann. — printed p.12 (§3.2) and p.30 (§6.2.2.3)', verification_note='md-verified 2026-09-05 (§3.2/§6.2.2.3, printed p.12/30) [VC]; caveat: value is the authority''s emission target, not printed in the source (engineer_input)', verified_at=now() where id='b8d7d74b-e519-466d-ae8e-051e1cae8dc5' and verification_status not in ('verified_against_standard','corrected');
-- eta_B_soll
update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $\eta_{\mathrm{B}, \mathrm{soll}}$ & - & erforderlicher, mittlerer jährlicher Frachtrückhalt im Retentionsbodenfilterbecken | Der erforderliche Frachtwirkungsgrad der Retentionsbodenfilteranlage ergibt sich aus der Emissions-/Immissionsanalyse und ist mit den Aufsichtsbehörden abzustimmen. Darauf basierend muss $\eta_{\mathrm{B}, \text { soll }}$ errechnet werden. — printed p.13 (§3.2) and p.27 (§6.2.2.1)', verification_note='md-verified 2026-09-05 (§3.2/§6.2.2.1, printed p.13/27) [VC]', verified_at=now() where id='9ca7e770-5399-4017-a733-6dc8b0eaded7' and verification_status not in ('verified_against_standard','corrected');
-- h_FK_required
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand: | l Mischsystem $h_{\mathrm{FK}} \geq 0,75 \mathrm{~m}$, | Trennsystem und Straßenentwässerung $h_{\mathrm{FK}} \geq 0,50 \mathrm{~m}$. — printed p.23', verification_note='md-verified 2026-09-05 (§6.1.4.5, printed p.23) [VC]; caveat: the field holds the REQUIRED height (a standard_fixed limit per system type) — no field carries the PLANNED h_FK, so REQ-12 checks the limit against itself (STAGED)', verified_at=now() where id='354446c4-be6d-40d7-9dcd-27899bad0792' and verification_status not in ('verified_against_standard','corrected');
-- filter_calcium_carbonate
update public.fields set verification_status='verified_against_standard', verification_quote='Das Filtermaterial muss einen Calciumcarbonatgehalt von $\geq 20$ Massen- $\%$ aufweisen. Der geforderte Calciumcarbonatgehalt kann bei geringer Ausstattung der regional vorkommenden Gesteinskörnungen durch technisches Zumischen carbonatreichen Materials erreicht werden. — printed p.23', verification_note='md-verified 2026-09-05 (§6.1.4.6, printed p.23) [VC]', verified_at=now() where id='66d0c1c8-5258-4a79-8a29-2dcc05413e9e' and verification_status not in ('verified_against_standard','corrected');
-- filter_U
update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $U$ & - & Ungleichförmigkeitsgrad ( $U=d_{60} / d_{10}$ ) | Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden. — printed p.12 (§3.2) and p.23 (§6.1.4.6)', verification_note='md-verified 2026-09-05 (§3.2/§6.1.4.6, printed p.12/23) [VC]', verified_at=now() where id='8a494645-c31f-4408-96a4-8c0125d4ed83' and verification_status not in ('verified_against_standard','corrected');
-- becken_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Das Retentionsbodenfilterbecken kann als Durchlauffilterbecken (Filterbeckenüberlauf im Retentionsbodenfilterbecken) oder als Fangfilterbecken (Filterbeckenüberlauf vor dem Retentionsbodenfilterbecken) konstruiert werden (Bild 2 und Bild 3). | Stoffliche Bodenfilteroberflächenbelastung bei Fangfilterbecken: | Stoffliche Bodenfilteroberflächenbelastung bei Durchlauffilterbecken: — printed p.19 (§6.1.2) and p.29 (§6.2.2.3)', verification_note='md-verified 2026-09-05 (§6.1.2/§6.2.2.3, printed p.19/29) [VC]; caveat: the third configuration "Durchlauffilterbecken mit Regenrückhaltelamelle" (Gl. 7) is selected via A178-07.rrl_vorhanden', verified_at=now() where id='5e789ceb-7cff-44f6-b21c-9d9c3850f0c6' and verification_status not in ('verified_against_standard','corrected');
-- rrl_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn es die Höhenverhältnisse zulassen, kann aus Kostengründen und zur Unterhaltungsoptimierung eine Regenrückhaltelamelle (Rückhalteraum) über dem Retentionsraum des Retentionsbodenfilterbeckens angeordnet werden. Diese ist, wie eine nachgeschaltete Regenrückhalteanlage, mit einer eigenen Drosseleinrichtung auszustatten (siehe 6.2.3). — printed p.25', verification_note='md-verified 2026-09-05 (§6.1.5, printed p.25) [VC]', verified_at=now() where id='8f300e5c-c49d-4d55-ab8c-716d3c16d842' and verification_status not in ('verified_against_standard','corrected');
-- filter_ueberkornanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\mathrm{G}_{\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\leq 15$ Massen- $\%$ und ein maximaler Feinanteil $(<0,063 \mathrm{~mm})$ von $\leq 3$ Massen- $\%$ festgelegt. — printed p.23', verification_note='md-verified 2026-09-05 (§6.1.4.6, printed p.23) [VC]', verified_at=now() where id='f247f671-ab21-4780-a074-78882c06d834' and verification_status not in ('verified_against_standard','corrected');
-- filter_feinanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist demnach unter anderem ein maximaler Überkornanteil von $\leq 15$ Massen- $\%$ und ein maximaler Feinanteil $(<0,063 \mathrm{~mm})$ von $\leq 3$ Massen- $\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. | Gerade bei diesen Filtern ist die Begrenzung des Feinanteils im Filtermaterial daher unbedingt einzuhalten. — printed p.23', verification_note='md-verified 2026-09-05 (§6.1.4.6, printed p.23) [VC]', verified_at=now() where id='f64ede7a-2a9b-4136-be5c-e00357e75c80' and verification_status not in ('verified_against_standard','corrected');
-- abdichtung_kdb_staerke
update public.fields set verification_status='verified_against_standard', verification_quote='Die Abdichtung gewährleistet dauerhaft einen kontrollierten Filterbetrieb und die Möglichkeit des Einstaus und ist daher zwingend erforderlich. Die Abdichtung muss mit Kunststoffdichtungsbahnen einer Stärke von mindestens 2 mm ausgeführt werden. Die Abdichtung ist beidseitig gegen mechanische Beschädigungen durch ein Geotextil zu schützen. — printed p.24', verification_note='md-verified 2026-09-05 (§6.1.4.9, printed p.24) [VC]', verified_at=now() where id='caf2c17e-822d-413d-b5a2-38a00295823e' and verification_status not in ('verified_against_standard','corrected');
-- geotextil_zwischen_filter_drane
update public.fields set verification_status='verified_against_standard', verification_quote='Zwischen Filterkörper und Dränschicht darf kein Geotextil eingebaut werden, da hierdurch das Kolmationsrisiko der Anlage steigt. | Die Filterstabilität des Filtermaterials zum Dränmaterial muss gewährleistet sein. Sie ist vom Auftragnehmer vor dem Einbau nachzuweisen. Ein Einbau von Geotextilien ist aufgrund der Kolmationsgefahr nicht zulässig. — printed p.23 (§6.1.4.5) and p.33 (§7.2)', verification_note='md-verified 2026-09-05 (§6.1.4.5/§7.2, printed p.23/33) [VC]', verified_at=now() where id='ff7a7070-b32f-4a1a-8a90-a49d7c2738a3' and verification_status not in ('verified_against_standard','corrected');
-- b_krit
update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $b_{\text {krit }}$ & $\mathrm{kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ & zulässige mittlere jährliche spezifische Filterflächenbelastung mit AFS63 bezogen auf die Bodenfilteroberfläche | Zur Gewährleistung eines wartungsarmen Betriebs und zur Minimierung des Kolmationsrisikos wird eine maximal zulässige AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ festgesetzt. — printed p.12 (§3.2) and p.26 (§6.2.2.1)', verification_note='md-verified 2026-09-05 (§3.2/§6.2.2.1, printed p.12/26) [VC]; caveat: standard_fixed 7 kg/(m²·a) held in a UI-editable field (STAGED read-only)', verified_at=now() where id='7780c33a-759a-472e-9f4f-0a8711a6da03' and verification_status not in ('verified_against_standard','corrected');
-- q_Dr_RBF
update public.fields set verification_status='verified_against_standard', verification_quote='3.2 Symbole und Formelzeichen | $q_{\text {Dr, RBF }}$ & $\mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ & Drosselabflussspende des Filterkörpers über das Drosselorgan, bezogen auf einen Wasserstand in Höhe des Filterbeckenüberlaufs | Es ist sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\text {Dr,RBF }}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Eine Steuerung oder Regelung des Drosselabflusses ist nicht erforderlich. — printed p.12 (§3.2) and p.25 (§6.1.4.10)', verification_note='md-verified 2026-09-05 (§3.2/§6.1.4.10, printed p.12/25) [VC]', verified_at=now() where id='72592f35-0ad6-499c-a975-11268a07bb1d' and verification_status not in ('verified_against_standard','corrected');
-- v_spez_grobstoff
update public.fields set verification_status='verified_against_standard', verification_quote='Gemäß 6.1.3 ist ein unbelüfteter Grobstoffrückhalt vorzusehen, der für den Rückhalt mineralischer Grobpartikel (Sand und Kies) ausgelegt ist. Das erforderliche spezifische Sammelvolumen wird auf mindestens $0,5 \mathrm{~m}^{3} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ festgelegt. — printed p.26', verification_note='md-verified 2026-09-05 (§6.2.1.2, printed p.26) [VC]; caveat: is_required=false although block gate REQ-10 reads it for trenn/strasse (STAGED)', verified_at=now() where id='70673e5f-e245-4b58-ab48-832287987066' and verification_status not in ('verified_against_standard','corrected');
-- pflanzdichte
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Bepflanzung werden vorkultivierte Schilfpflanzen (Phragmites communis) eingesetzt. Als Pflanzdichte haben sich 4 bis 8 Pflanzen je Quadratmeter bewährt. Eine Fertigstellungspflege ist erforderlich. — printed p.24', verification_note='md-verified 2026-09-05 (§6.1.4.7, printed p.24) [VC]; caveat: empirical "haben sich ... bewährt" wording — block gate REQ-27 over-enforces (STAGED block→warn, D7 class)', verified_at=now() where id='2a51d230-518f-4d3e-a024-ef72130a8cd4' and verification_status not in ('verified_against_standard','corrected');

