update public.fields set verification_status='verified_against_standard', verification_quote='In erster Näherung kann angenommen werden, dass ca. $1 \%$ der angeschlossenen befestigten Flächen ( $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ ) als Bodenfilteroberfläche benötigt wird. | spezifische Bodenfilteroberfläche $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha}$ angeschlossener befestigte Fläche ( $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ ); — printed p.18 (§5.3) and p.28 (§6.2.2.2)', verification_note='md-verified 2026-09-05 (§5.3/§6.2.2.2, printed p.18/28) [VC]; caveat: UNIT: the source gives m² per ha A_E,b,a; "m²/(ha·red)" (reduced area) is not this guideline''s nomenclature; clause_reference §5.3 → §6.2.2.2 (STAGED)', verified_at=now() where id='0b279978-4693-459b-9439-c5864e073e94' and verification_status not in ('verified_against_standard','corrected');
