update public.fields set verification_status='verified_against_standard', verification_quote='Es ist sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\text {Dr,RBF }}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Eine Steuerung oder Regelung des Drosselabflusses ist nicht erforderlich. — printed p.25', verification_note='md-verified 2026-09-05 (§6.1.4.10, printed p.25) [VC]; caveat: DUPLICATE of A178-07.q_Dr_RBF (same 0,05 l/(s·m²) limit); clause_reference §5.3 wrong (STAGED)', verified_at=now() where id='a2b492b2-7cc3-4c19-b77f-5da09c0e2cff' and verification_status not in ('verified_against_standard','corrected');
-- a178_A_RBF_min
update public.fields set verification_status='verified_against_standard', verification_quote='Im Trennsystem ist bei einer mittleren Jahresniederschlagshöhe von $>1.000 \mathrm{~mm} / \mathrm{a}$ eine Filterfläche $\operatorname{von} A_{\mathrm{F}}=100 \mathrm{~m}^{2}$ je Hektar befestigter, angeschlossener Fläche ( $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ ) anzusetzen, um einer Filterüberlastung entgegenzuwirken. | spezifische Bodenfilteroberfläche $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha}$ angeschlossener befestigte Fläche ( $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ ); — printed p.27 (§6.2.2.1) and p.28 (§6.2.2.2)', verification_note='md-verified 2026-09-05 (§6.2.2.1/§6.2.2.2, printed p.27/28) [VC]; caveat: minimum area = 100 m²/ha only for Trennsystem >1.000 mm/a and for the simplified road case; clause_reference §5.3 wrong (STAGED)', verified_at=now() where id='482cdb0b-2e98-4f67-9621-2e0397b66df9' and verification_status not in ('verified_against_standard','corrected');

