update public.equations set verification_status='verified_against_standard', verification_quote='Als Mindestanforderung ist der Nachweis zu führen, dass mit der gewählten Anlagenkonfiguration die emissionsorientierten Vorgaben bzgl. der zulässigen spezifischen jährlichen Einleitfracht (AFS63) aus der Retentionsbodenfilteranlage $b_{\text {R, }, \text { zul }}$ für die Zielgröße AFS63 erreicht werden kann. | Spezifische Einleitfracht aus der Retentionsbodenfilteranlage: | \frac{B_{\mathrm{RBFA}, \mathrm{ab}}}{A_{\mathrm{E}, \mathrm{~b}, \mathrm{a}}} \leq b_{\mathrm{R}, \mathrm{e}, \mathrm{zul}} \tag{10} — printed p.30', verification_note='md-verified 2026-09-05 (§6.2.2.3 Gl. (10), printed p.30) [VC]', verified_at=now() where id='b3085f29-7a03-4021-ba9b-45addc5d91df' and verification_status <> 'verified_against_standard';
-- Gl. (9) A178-16 b_F_im_bereich
update public.equations set verification_status='verified_against_standard', verification_quote='Der Nachweis ist erfüllt, wenn in der betreffenden Anlagenkonfiguration (GL. 5 bis GL. 7) die nachgewiesene Bodenfilteroberflächenbelastung $b_{\mathrm{F}}$ die zulässige Bodenfilteroberflächenbelastung $b_{\text {krit }}$ gemäß 6.2.2.1 einhält: | Zulässige AFS63-Bodenfilteroberflächenbelastung: | 4 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right) \leq b_{F} \leq b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right) \tag{9} — printed p.30', verification_note='md-verified 2026-09-05 (§6.2.2.3 Gl. (9), printed p.30) [VC]; note: D3: the md prints Gl. (9) as the double inequality 4 ≤ b_F ≤ b_krit = 7 under the heading "Zulässige AFS63-Bodenfilteroberflächenbelastung"; the lead sentence names only the upper bound', verified_at=now() where id='b4167409-558e-4744-8b6f-049c469f085c' and verification_status <> 'verified_against_standard';

